import pandas as pd
import numpy as np

def task_func(days, random_seed=0):
    if isinstance(days, bool) or not isinstance(days, (int, np.integer)):
        raise TypeError("days must be a non-negative integer")
    if days < 0:
        raise ValueError("days must be non-negative")

    columns = ["Groceries", "Entertainment", "Rent", "Utilities", "Miscellaneous"]
    index = pd.date_range(start="2023-01-01", periods=days, freq="D")

    np.random.seed(random_seed)
    data = np.random.randint(0, 101, size=(days, len(columns)))

    return pd.DataFrame(data, index=index, columns=columns)
